birthdays = {'Alice': 'Apr 1', 'Bob': 'Dec 12'}
# the typing of a person, scripted in a list
typed = iter(['Alice', 'Eve', 'Dec 5', 'Eve', ''])
name = next(typed)
while name != '':
    if name in birthdays:
        print(name, 'has birthday', birthdays[name])
    else:
        # an unknown name takes the next typed line as its date
        birthdays[name] = next(typed)
        print('Learned', name, birthdays[name])
    name = next(typed)

board = {'a1': 'wR', 'e1': 'wK', 'e8': 'bK'}
files = 'abcdefgh'
# walk the ranks from 8 down to 1, as a diagram is drawn
for r in range(8, 0, -1):
    row = []
    for f in files:
        # an empty square prints as two dots
        row.append(board.get(f + str(r), '..'))
    print(r, ' '.join(row))

# build the set of all 64 legal square names
squares = set()
for f in 'abcdefgh':
    for r in '12345678':
        squares.add(f + r)
# a position with one impossible square, z9
board = {'e1': 'wK', 'e8': 'bK', 'z9': 'wQ'}
bad = []
for s in board:
    if s not in squares:
        bad.append(s)
# collect the kings from the values
kings = []
for p in board.values():
    if p[1] == 'K':
        kings.append(p)
kings.sort()
print(bad, kings, kings == ['bK', 'wK'])

# each guest is a key; the value is a dictionary of the basket
alice = {'apples': 5, 'pretzels': 12}
bob = {'apples': 2, 'ham sandwiches': 3}
guests = {'Alice': alice, 'Bob': bob}
# add up one item over all guests
def total(item):
    result = 0
    for basket in guests.values():
        result += basket.get(item, 0)
    return result
print(total('apples'), total('cups'))
print(guests['Alice']['pretzels'])
